sform:translateY(-50%);z-index:1;font-size:112px;filter:drop-shadow(0 10px 1px #8b9b6030);animation:float 3s ease-in-out infinite}.hero-art:after{content:'✦';position:absolute;font-size:28px;right:-34px;top:3px;color:#efa946}@keyframes float{50%{transform:translateY(calc(-50% - 8px)) rotate(3deg)}}.primary{border:0;border-radius:14px;background:#243f36;color:#fff;padding:14px 21px;font-weight:900;box-shadow:0 5px 0 #182c26;transition:.15s}.primary:hover{transform:translateY(-2px);box-shadow:0 7px 0 #182c26}.primary:active{transform:translateY(3px);box-shadow:0 2px 0 #182c26}.secondary{border:1px solid #c9d5c4;background:#fff;border-radius:14px;padding:13px 18px;font-weight:900}.section-head{display:flex;align-items:end;justify-content:space-between;margin:33px 0 16px}.section-head h2{font:900 23px Nunito;margin:0;letter-spacing:-.6px}.section-head p{margin:5px 0 0;color:var(--muted);font-size:13px}.stage-grid{display:grid;grid-template-columns:repeat(10,1fr);gap:10px}.stage-dot{aspect-ratio:1;border:1px solid var(--line);border-radius:18px;background:#fff;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:4px;box-shadow:0 3px 0 #e7eae3;transition:.16s;position:relative}.stage-dot:hover:not(:disabled){transform:translateY(-3px)}.stage-dot b{font:900 17px Nunito}.stage-dot span{font-size:10px}.stage-dot:disabled{opacity:.42;cursor:not-allowed}.stage-dot.done:after{content:'★';position:absolute;right:6px;top:4px;font-size:10px;color:#e9a43c}.easy{--tone:#64a873;--tint:#e4f3df}.medium{--tone:#e3a23a;--tint:#fff1d9}.hard{--tone:#e5655c;--tint:#ffebe7}.veryhard{--tone:#9870cb;--tint:#f1e8fb}.hell{--tone:#362933;--tint:#fbe2e0}.stage-dot{border-color:color-mix(in srgb,var(--tone) 23%,white)}.stage-dot b{color:var(--tone)}.stage-dot.active{background:var(--tint)}.below-grid{margin-top:27px;display:grid;grid-template-columns:1.2fr .8fr;gap:16px}.info-card,.tip-card{background:#fff;border:1px solid var(--line);border-radius:22px;padding:20px 22px