.playbar{display:grid;grid-template-columns:1fr auto;align-items:center;gap:18px;margin:4px 0 22px}.playstats{display:flex;gap:9px}.stat{padding:9px 13px;background:#fff;border:1px solid var(--line);border-radius:13px;font-size:12px;font-weight:900;white-space:nowrap}.stat .label{color:#83908b;margin-right:5px}.stage-card{max-width:840px;margin:0 auto;background:#fff;border:1px solid var(--line);border-radius:28px;padding:28px 34px;box-shadow:var(--shadow)}.stage-kicker{display:flex;align-items:center;gap:8px;font-size:11px;font-weight:900;letter-spacing:1.1px;text-transform:uppercase;color:var(--tone)}.difficulty{padding:5px 9px;border-radius:8px;background:var(--tint);font-size:10px}.stage-title{font:900 clamp(25px,3vw,34px)/1.13 Nunito;margin:12px 0 8px;letter-spacing:-1px}.stage-desc{color:#728087;font-size:14px;line-height:1.55;margin:0 0 20px}.prompt-box{border:1px solid #e7ebe4;background:#f8faf6;border-radius:18px;padding:19px;margin:18px 0}.prompt-box h3{font:900 18px Nunito;margin:0 0 7px}.prompt-box p{font-size:13px;line-height:1.55;color:#66767a;margin:0}.options{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:15px 0}.option{min-height:55px;text-align:left;border:1px solid #e2e8e1;background:#fff;border-radius:15px;padding:13px 15px;font-weight:800;transition:.15s}.option:hover:not(:disabled){border-color:#a6c58e;background:#f8fcf3;transform:translateY(-1px)}.option.correct{background:#e5f5e1;border-color:#79bd74;color:#2d753d}.option.wrong{background:#fff0eb;border-color:#ec8b77;color:#ae4a37}.option:disabled{cursor:default}.feedback{display:none;border-radius:14px;padding:13px 15px;font-size:13px;line-height:1.5;margin:12px 0;font-weight:600}.feedback.show{display:block}.feedback.good{background:#e9f6e5;color:#347047}.feedback.bad{background:#fff0ec;color:#9e4939}.feedback strong{font-weight:900}.tip{background:#fff8df;border:1px solid #f3e8b8;border-radius:14px;padding:12px 15px;color:#786335;font-size:12px;line-height:1.5;margin:20px 0}.tip b{color:#826320}.card-bottom{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-top:20px}.card-bottom .progress-track{flex:1}.next-btn{min-width:132px}.hell-screen{background:#26202b;color:#fff}.hell-screen .stage-card{border-color:#5d3b3e;background:#302a34}.hell-screen .prompt-box{background:#3a333d;border-color:#524752}.hell-screen .prompt-box p,.hell-screen .stage-desc{color:#d5c9d1}.hell-screen .option{background:#3d3540;border-color:#64505c;color:white}.hell-screen .option.correct{background:#28533e}.hell-screen .option.wrong{background:#673d3c}.hell-screen .tip{background:#46393a;border-color:#705044;color:#f0d7b3}.hell-screen .stat{background:#38313b;border-color:#5c4b57;color:#fff}.hell-screen .stage-title{color:#fff}.hell-screen .playbar .progress-track{background:#50464f}
