2;color:#995b26;font-size:11px;font-weight:800;line-height:1.4;margin-top:10px}.lab-step{font-size:10px;letter-spacing:1.1px;text-transform:uppercase;color:#7a8a7d;font-weight:900}.lab-thermo{display:flex;align-items:center;gap:10px}.lab-thermo input{flex:1;accent-color:#69aa67}.temp-read{font:900 16px Nunito;width:56px}.green-zone{color:#4b9b66;font-size:10px;font-weight:900}.stir-wrap{display:flex;align-items:center;gap:16px}.stir-pad{width:118px;height:118px;border-radius:50%;border:5px solid #dcebd4;background:#f6fbf3;position:relative;touch-action:none;user-select:none;cursor:grab;display:grid;place-items:center;flex:none}.stir-pad:active{cursor:grabbing}.stir-pad:before{content:'';position:absolute;inset:10px;border:2px dashed #9ab88e;border-radius:50%}.stir-pad .stir-arrow{font-size:32px;color:#58965a;animation:spin 3s linear infinite}.stir-pad.wrong{border-color:#ed8e81;background:#fff1ef}.stir-pad.wrong .stir-arrow{color:#d75e53}@keyframes spin{to{transform:rotate(360deg)}}.stir-progress{height:8px;background:#e7eee3;border-radius:9px;overflow:hidden;margin-top:9px}.stir-progress i{display:block;height:100%;background:#70b569;width:0;transition:width .15s}.stir-count{font:900 13px Nunito;margin-top:7px}.mold{display:none;font-size:74px;cursor:pointer;animation:bounce 1.2s infinite alternate}@keyframes bounce{to{transform:translateY(-7px)}}.lab-done{text-align:center;padding:25px 10px}.lab-done .soap-icon{font-size:76px}.confetti{position:fixed;inset:0;pointer-events:none;z-index:10;overflow:hidden}.confetti i{position:absolute;top:-15px;width:9px;height:13px;animation:fall 2.8s linear forwards}@keyframes fall{to{transform:translateY(110vh) rotate(720deg)}}
