const stages=[
{title:'Heat flows from hot to cold',level:'EASY',kind:'quiz',q:'A hot object is placed beside a colder object. Which way does heat energy flow?',opts:['From the colder object to the hotter one','From the hotter object to the colder one','Both objects lose all their heat','Heat does not move'],a:1,exp:'Heat moves from a higher temperature to a lower temperature until both reach thermal equilibrium. If 100°C water and 25°C water mix in equal amounts, the final temperature is (100 + 25) ÷ 2 = 62.5°C.',tip:'Heat always flows from hot to cold.'},
{title:'Three ways heat travels',level:'EASY',kind:'sort',q:'Match each example to the way heat is transferred.',items:[['Metal spoon warming in soup','Conduction'],['Warm air rising above a heater','Convection'],['The Sun warming your face','Radiation']],opts:['Conduction','Convection','Radiation'],exp:'Conduction transfers heat through touching particles; convection moves through liquids and gases; radiation travels as waves and needs no medium.',tip:'Hot fluids rise and cooler fluids sink—this circulation is a convection current.'},
{title:'Physical or chemical change?',level:'EASY',kind:'quiz',q:'Which change makes a new substance?',opts:['Ice melting','Paper being cut','Iron rusting','Sugar dissolving in water'],a:2,exp:'Rusting is a chemical change: iron reacts with oxygen and forms a new substance. Melting, cutting and dissolving are physical changes.',tip:'Ask: did a new substance form? If yes, it is a chemical change.'},
{title:'Clues that a reaction happened',level:'EASY',kind:'quiz',q:'Which set contains signs of a chemical reaction?',opts:['A precipitate, colour change, gas, or light and heat','A change in shape only','A solid becoming smaller','A substance moving to a new cup'],a:0,exp:'A reaction may form a precipitate (an insoluble solid), change colour, release a gas, or give off light and heat. CO₂ turns limewater milky.',tip:'Look for evidence—not just a change in size or shape.'},
{title:'Carbohydrate building blocks',level:'EASY',kind:'quiz',q:'Which pair are simple sugars, and which pair are double sugars?',opts:['Glucose & fructose; sucrose & maltose','Sucrose & glucose; fructose & maltose','Maltose & fructose; glucose & sucrose','All four are fats'],a:0,exp:'Glucose and fructose are monosaccharides (single sugar units). Sucrose and maltose are disaccharides (two joined sugar units).',tip:'Mono means one; di means two.'},
{title:'Balance nitrogen and hydrogen',level:'MEDIUM',kind:'balance',q:'Balance: N₂ + H₂ → NH₃',coeff:[1,1,1],answer:[1,3,2],labels:['N₂','H₂','NH₃'],exp:'N₂ + 3H₂ → 2NH₃. There are 2 nitrogen atoms and 6 hydrogen atoms on each side.',tip:'Change coefficients in front of formulas; never change subscripts.'},
{title:'Coefficients vs. subscripts',level:'MEDIUM',kind:'quiz',q:'In 2H₂O, how many hydrogen and oxygen atoms are there altogether?',opts:['2 H and 2 O','4 H and 2 O','2 H and 1 O','4 H and 1 O'],a:1,exp:'The coefficient 2 multiplies every atom in H₂O: 2 × 2 = 4 H atoms and 2 × 1 = 2 O atoms.',tip:'A coefficient multiplies the whole formula. Subscripts stay fixed.'},
{title:'Conservation of mass',level:'MEDIUM',kind:'quiz',q:'222 g of mercury oxide decomposes. It makes 206 g mercury. How much oxygen is released?',opts:['16 g','28 g','206 g','428 g'],a:0,exp:'By conservation of mass, total mass stays the same: 222 g − 206 g = 16 g oxygen. Lavoisier described this law.',tip:'Total mass of reactants = total mass of products.'},
{title:'Choose the right food test',level:'MEDIUM',kind:'quiz',q:'Which test is correctly matched to the nutrient?',opts:['Iodine — starch','Biuret — fats','Sudan III — protein','Benedict — vitamin C'],a:0,exp:'Iodine solution tests for starch (blue-black). Benedict’s tests for reducing sugars; Sudan III for fats; Biuret for proteins.',tip:'Iodine goes blue-black when starch is present.'},
{title:'Nutrients and their elements',level:'MEDIUM',kind:'quiz',q:'Which nutrient group contains nitrogen as well as carbon, hydrogen and oxygen?',opts:['Carbohydrates','Fats','Proteins','Water'],a:2,exp:'Carbohydrates and fats contain carbon, hydrogen and oxygen. Proteins also contain nitrogen.',tip:'Remember C, H, O—and N for proteins.'},
{title:'Balancing reactions',level:'HARD',kind:'balance',q:'Balance both equations. For the second, treat NO₃ as a group.',equations:['CH₄ + O₂ → CO₂ + H₂O','Mg + AgNO₃ → Mg(NO₃)₂ + Ag'],sets:[{labels:['CH₄','O₂','CO₂','H₂O'],answer:[1,2,1,2]},{labels:['Mg','AgNO₃','Mg(NO₃)₂','Ag'],answer:[1,2,1,2]}],exp:'CH₄ + 2O₂ → CO₂ + 2H₂O. Also Mg + 2AgNO₃ → Mg(NO₃)₂ + 2Ag. Count unchanged atoms on both sides.',tip:'Keep polyatomic groups together when they stay unchanged.'},
{title:'Nutrients and health',level:'HARD',kind:'quiz',q:'Which statement is correct?',opts:['Diabetes can involve too little insulin from the pancreas','Cholesterol always improves blood flow','Extra carbohydrate can never be stored','Insulin is made by the lungs'],a:0,exp:'The pancreas produces insulin, which helps control blood glucose. Too much cholesterol can contribute to blocked arteries. Extra carbohydrate can be stored.',tip:'Insulin helps move glucose from blood into body cells.'},
{title:'Soap ingredients & stirring',level:'HARD',kind:'soapmini',q:'Choose the measured amounts, then stir clockwise to start the soap recipe.',exp:'Oils react with sodium hydroxide in saponification to form soap. In real life, caustic soda is dangerous and must only be handled by a teacher.',tip:'Recipe: 100 mL oil + 30 mL caustic soda. Heat gently to 40–50°C, then stir clockwise.'},
{title:'60-second mixed lab sprint',level:'VERY HARD',kind:'timed',seconds:60,questions:[['Heat transfer through a metal spoon is…',['Conduction','Radiation','Convection'],0],['Which test detects protein?',['Biuret','Iodine','Sudan III'],0],['Hot air usually…',['Rises','Sinks','Freezes'],0],['A gas forming can be a sign of…',['Chemical reaction','Physical sorting','Melting only'],0],['Radiation needs…',['No medium','A liquid','A metal'],0],['Which nutrient can contain nitrogen?',['Protein','Fat only','Water'],0]],exp:'You raced through a mixed review of heat, reactions and food tests.',tip:'Read carefully, then trust the evidence.'},
{title:'True or false: lab traps',level:'VERY HARD',kind:'tf',questions:[['You may change a subscript to balance an equation.',false],['Proteins are the body’s major energy source.',false],['Radiation can travel through empty space.',true],['A precipitate is an insoluble solid formed in a reaction.',true],['Convection happens in liquids and gases.',true]],exp:'Balance equations by changing coefficients only. Proteins build and repair; carbohydrates and fats are the main energy sources.',tip:'Never alter a formula’s subscripts when balancing.'},
{title:'Complete the equations',level:'VERY HARD',kind:'complete',sets:[{text:'C + O₂ → ?',opts:['CO₂','CO','C₂O'],a:0,exp:'C + O₂ → CO₂. One carbon atom and two oxygen atoms are conserved.'},{text:'Ca + O₂ → ?',opts:['CaO','CaO₂','Ca₂O'],a:0,exp:'2Ca + O₂ → 2CaO. Calcium oxide forms; coefficients balance the atoms.'}],exp:'Atoms are rearranged in a chemical reaction, not created or destroyed.',tip:'First identify the product, then balance its atoms.'},
{title:'Spot the balancing error',level:'VERY HARD',kind:'error',questions:[['2H₂ + O₂ → 2H₂O',['Balanced','Not balanced'],0],['N₂ + H₂ → 2NH₃',['Balanced','Not balanced'],1],['2Mg + O₂ → 2MgO',['Balanced','Not balanced'],0],['CH₄ + 2O₂ → CO₂ + 2H₂O',['Balanced','Not balanced'],0]],exp:'For N₂ + H₂ → 2NH₃, hydrogen is not balanced (2 on left, 6 on right). It needs 3H₂.',tip:'Count each kind of atom on both sides before deciding.'},
{title:'HELL QUIZ — 8 rapid questions',level:'HELL IN A CELL',kind:'hellquiz',seconds:45,questions:[['Heat flows…',['Hot → cold','Cold → hot'],0],['Iodine tests for…',['Starch','Protein'],0],['Protein test?',['Biuret','Benedict'],0],['Gas + bubbles can show…',['Reaction','Melting'],0],['Radiation speed?',['300,000 km/s','300 km/s'],0],['Caustic soda formula?',['NaOH','CO₂'],0],['Cholesterol may block…',['Arteries','Bones'],0],['Convection occurs in…',['Fluids','Vacuum'],0]],exp:'Eight rapid checks complete. The lab awaits your final balancing challenge!',tip:'Stay calm: quick thinking, accurate science.'},
{title:'HELL BALANCING — glucose combustion',level:'HELL IN A CELL',kind:'balance',q:'Balance the glucose combustion equation.',coeff:[1,1,1,1],answer:[1,6,6,6],labels:['C₆H₁₂O₆','O₂','CO₂','H₂O'],exp:'C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O. Check C: 6, H: 12, O: 18 on each side.',tip:'Balance carbon first, then hydrogen, then oxygen.'},
{title:'FINAL BOSS — The Soap Lab',level:'HELL IN A CELL',kind:'soap',exp:'Saponification is the reaction of oil (fat) with sodium hydroxide. It forms soap and glycerol—a new substance with a new consistency.',tip:'Measure carefully, heat gently, and make three full clockwise turns.'}
];
