function footer(){return '<div class="footer">Designed by Mister Ahmed Abdelhadi for his lovely students</div>'}
function levelClass(level){return level==='EASY'?'easy':level==='MEDIUM'?'medium':level==='HARD'?'hard':level==='VERY HARD'?'veryhard':'hell'}
function header(){return `<header class="topbar shell"><div class="brand"><div class="brandmark">🧪</div><div>Mister Ahmed's Science Lab<small>Matter Adventure</small></div></div><div class="nav-actions"><button class="soft-btn" onclick="home()">⌂ &nbsp;Home</button><button class="icon-btn" title="Reset game" onclick="resetGame()">↻</button></div></header>`}
function home(){stopTimer();document.body.className='';app.innerHTML=`${header()}<main class="screen shell"><section class="hero"><div class="hero-copy"><div class="eyebrow">A hands-on science adventure</div><h1>Welcome to the<br><em>Science Lab!</em></h1><p>Master matter, heat, reactions and nutrition. Then step up to the Soap Lab and earn your title as Soap Master.</p><button class="primary" onclick="startStage(${unlocked})">${unlocked===1?'Start your adventure':'Continue Stage '+unlocked} &nbsp;→</button></div><div class="hero-art">🧑‍🔬</div></section><div class="section-head"><div><h2>Your stage map</h2><p>Finish each stage to unlock the next. Collect stars as you go.</p></div><div class="stat">⭐ ${score} points</div></div><div class="stage-grid">${stages.map((s,i)=>`<button class="stage-dot ${levelClass(s.level)} ${i+1<=unlocked?'active':''} ${i+1<unlocked?'done':''}" ${i+1>unlocked?'disabled':''} onclick="startStage(${i+1})" title="${esc(s.title)}"><b>${i+1}</b><span>${i+1>unlocked?'🔒':i+1<unlocked?'⭐':'▶'}</span></button>`).join('')}</div><div class="below-grid"><article class="info-card"><h3>🧭 How to play</h3><p>Answer questions, sort examples and balance equations. A wrong answer costs one heart. If you run out, you’ll retry that stage. Use your science knowledge—and read Mister Ahmed’s tip!</p></article><article class="info-card practice"><div><h3>🧼 Practice Soap Lab</h3><p>Try the interactive soap-making challenge anytime.</p></div><button class="primary" onclick="startPractice()">Enter lab →</button></article></div>${footer()}</main>`}
function stats(){return `<div class="playstats"><div class="stat"><span class="label">SCORE</span>⭐ ${score}</div><div class="stat"><span class="label">LIVES</span>${'❤️'.repeat(lives)}${'♡'.repeat(3-lives)}</div>${timeLeft?`<div class="stat" id="timer-stat"><span class="label">TIME</span>⏱ <b id="time-count">${timeLeft}</b>s</div>`:''}</div>`}
function startStage(n){stopTimer();current=n;practice=false;lives=3;answered=false;subIndex=0;timeLeft=0;renderStage()}
function startPractice(){stopTimer();current=20;practice=true;lives=3;answered=false;subIndex=0;renderSoap(true)}
function renderStage(){const s=stages[current-1];if(s.kind==='soap'){renderSoap(false);return}document.body.className=s.level==='HELL IN A CELL'?'hell-screen':'';const hell=s.level==='HELL IN A CELL',pct=Math.round((current-1)/20*100);let body='';
if(s.kind==='quiz'||s.kind==='sort'){body=`<div class="prompt-box"><h3>${esc(s.q)}</h3>${s.kind==='sort'?`<p>Tap the correct match for each example.</p>`:''}</div>${s.kind==='sort'?s.items.map((it,i)=>`<div class="sort-row"><b>${esc(it[0])}</b><div class="options">${s.opts.map(o=>`<button class="option" onclick="sortAnswer(${i},'${o}')">${o}</button>`).join('')}</div></div>`):`<div class="options">${s.opts.map((o,i)=>`<button class="option" onclick="answer(${i===s.a})">${esc(o)}</button>`).join('')}</div>`}`}
if(s.kind==='balance'){body=balanceUI(s)}
if(s.kind==='timed'||s.kind==='hellquiz'||s.kind==='tf'||s.kind==='error'){body=rapidUI(s)}
if(s.kind==='complete'){body=completeUI(s)}
if(s.kind==='soapmini'){body=miniSoapUI()}
app.innerHTML=`${header()}<main class="screen shell"><div class="playbar"><div><div class="progress-meta"><span>STAGE ${current} / 20</span><span>${pct}% complete</span></div><div class="progress-track"><i style="width:${pct}%"></i></div></div>${stats()}</div><section class="stage-card ${levelClass(s.level)}"><div class="stage-kicker"><span>${s.level==='HELL IN A CELL'?'🔥 💀 ':''}Stage ${current}</span><span class="difficulty">${s.level}</span></div><h1 class="stage-title">${esc(s.title)}</h1><p class="stage-desc">${current===20?'One final challenge. Follow each step carefully to make your own soap!':'Show what you know to move one step closer to Soap Master.'}</p>${body}<div class="feedback" id="feedback"></div><div class="tip"><b>💡 Mister Ahmed’s Tip:</b> ${esc(s.tip)}</div><div class="card-bottom"><div class="progress-track"><i style="width:${pct}%"></i></div><button class="primary next-btn" id="next-btn" onclick="nextStage()" ${answered?'':'disabled'}>${current===20?'Finish lab':'Next stage'} →</button></div></section>${footer()}</main>`;
if(s.seconds){timeLeft=s.seconds;startTimer();}
}

