function resetGame(){if(confirm('Restart your adventure and clear your score?')){localStorage.removeItem('soap-unlocked');localStorage.removeItem('soap-score');score=0;unlocked=1;home()}}
let labStep=0,oilAmount=0,sodaAmount=0,tempValue=25,stirRadians=0,lastAngle=null,wrongStir=false,soapPracticeMode=false;
function miniSoapUI(){labStep=labStep||0; if(labStep===0)return `<div class="prompt-box"><h3>Step 1 · Measure the oil</h3><p>Choose the recipe amount for our beaker.</p></div><div class="options">${[50,100,150].map(v=>`<button class="option" onclick="miniAmount('oil',${v})">🫒 ${v} mL oil</button>`).join('')}</div>`;if(labStep===1)return `<div class="prompt-box"><h3>Step 2 · Add caustic soda</h3><p>Choose the correct amount of sodium hydroxide (NaOH).</p></div><div class="lab-alert">⚠️ Caustic soda is dangerous—teacher only in real life!</div><div class="options">${[20,30,50].map(v=>`<button class="option" onclick="miniAmount('soda',${v})">🧪 ${v} mL NaOH</button>`).join('')}</div>`;if(labStep===2)return `<div class="prompt-box"><h3>Step 3 · Stir clockwise ↻</h3><p>Drag around the pad clockwise. Complete one full turn to finish this practice step.</p></div>${stirPadMarkup(1)}`;return `<div class="feedback show good">✓ Recipe prepared! ${stages[12].exp}</div>`}
function miniAmount(which,n){if((which==='oil'&&n===100)||(which==='soda'&&n===30)){if(which==='oil'){oilAmount=n;labStep=1}else{sodaAmount=n;labStep=2;stirRadians=0}renderStage()}else{lives--;refreshStats();showFeedback(false,which==='oil'?'Measure exactly 100 mL of oil.':'The recipe uses 30 mL of caustic soda.');if(!lives)setTimeout(()=>{lives=3;labStep=0;renderStage()},1000)}}
function stirPadMarkup(turns){return `<div class="stir-wrap"><div class="stir-pad" id="stir-pad" aria-label="Drag clockwise to stir"><span class="stir-arrow">↻</span></div><div><b>Stir clockwise ↻</b><div style="font-size:12px;color:#74817e;margin-top:5px">${turns===1?'1 full rotation':'3 full rotations'} required</div><div class="stir-progress"><i id="stir-fill" style="width:${Math.min(100,stirRadians/(Math.PI*2*turns)*100)}%"></i></div><div class="stir-count" id="stir-count">${Math.min(turns,Math.floor(stirRadians/(Math.PI*2)))} / ${turns} turns</div><div id="stir-warning" style="color:#c84f46;font-weight:900;font-size:11px;margin-top:5px"></div></div></div>`}
function bindStir(turns,isMini){const pad=document.querySelector('#stir-pad');if(!pad)return;pad.onpointerdown=e=>{e.preventDefault();pad.setPointerCapture(e.pointerId);const r=pad.getBoundingClientRect();lastAngle=Math.atan2(e.clientY-(r.top+r.height/2),e.clientX-(r.left+r.width/2))};pad.onpointermove=e=>{if(lastAngle===null)return;const r=pad.getBoundingClientRect(),a=Math.atan2(e.clientY-(r.top+r.height/2),e.clientX-(r.left+r.width/2));let d=a-lastAngle;while(d>Math.PI)d-=Math.PI*2;while(d< -Math.PI)d+=Math.PI*2;lastAngle=a;if(d>0){stirRadians+=d;wrongStir=false;pad.classList.remove('wrong')}else if(d<-.04){wrongStir=true;pad.classList.add('wrong');const warn=document.querySelector('#stir-warning');if(warn)warn.textContent='WRONG DIRECTION! Clockwise only!'}const required=Math.PI*2*turns;const fill=document.querySelector('#stir-fill');if(fill)fill.style.width=Math.min(100,stirRadians/required*100)+'%';const count=document.querySelector('#stir-count');if(count)count.textContent=`${Math.min(turns,Math.floor(stirRadians/(Math.PI*2)))} / ${turns} turns`;if(stirRadians>=required){lastAngle=null;if(isMini){labStep=3;answer(true,stages[12].exp);return}labStep=4;renderSoap(false)}};pad.onpointerup=pad.onpointercancel=()=>{lastAngle=null}}
function renderSoap(isPractice){soapPracticeMode=isPractice;document.body.className='hell-screen';const title=isPractice?'Practice Soap Lab':'Stage 20 · Final Boss';const progress=labStep<4?Math.round(labStep/5*100):100;let control='';let liquidHeight=oilAmount?38:4,liquidColor=labStep>=3?'#d4b766':'#efc780';if(labStep===0)control=`<div class="lab-step">STEP A · MEASURE</div><div class="lab-control"><h4>Add exactly 100 mL of oil</h4><p>Tap the correct measuring cup amount and pour it into the beaker.</p><div class="options">${[50,100,150].map(n=>`<button class="option" onclick="labMeasure('oil',${n})">🫒 ${n} mL</button>`).join('')}</div><div class="lab-alert">Choose 100 mL. Check the measuring marks before pouring.</div></div>`;if(labStep===1)control=`<div class="lab-step">STEP B · ADD CAREFULLY</div><div class="lab-control"><h4>Add 30 mL of caustic soda (NaOH)</h4><p>Measure carefully, then add it to the oil.</p><div class="options">${[20,30,50].map(n=>`<button class="option" onclick="labMeasure('soda',${n})">🧪 ${n} mL NaOH</button>`).join('')}</div><div class="lab-alert">⚠️ Caustic soda is dangerous — teacher only in real life!</div></div>`;if(labStep===2)control=`<div class="lab-step">STEP C · GENTLE HEAT</div><div class="lab-control"><h4>Warm the mixture to 40–50°C</h4><p>Use the burner slider. Keep the thermometer in the green zone.</p><div class="lab-thermo"><span>🔥</span><input id="temp-slider" type="range" min="20" max="70" value="${tempValue}" oninput="tempValue=+this.value;document.querySelector('#temp-number').textContent=tempValue+'°C';document.querySelector('#temp-number').style.color=tempValue>=40&&tempValue<=50?'#4b9b66':tempValue>50?'#d85e54':'#81908b'"><b class="temp-read" id="temp-number">${tempValue}°C</b></div><div class="green-zone">GREEN ZONE · 40–50°C</div><button class="primary" style="margin-top:12px" onclick="labHeat()">Set temperature ✓</button></div>`;if(labStep===3)control=`<div class="lab-step">STEP D · THE KEY MECHANIC</div><div class="lab-control"><h4>Stir clockwise ↻</h4><p>Drag in a circle CLOCKWISE around the beaker. Complete 3 full turns.</p>${stirPadMarkup(3)}</div>`;if(labStep===4)control=`<div class="lab-step">STEP E · POUR, WAIT & CUT</div><div class="lab-control"><h4>${soapState===0?'Pour into the soap mold':soapState===1?'Let the soap set, then tap to cut':'Soap formed!'}</h4><p>${soapState===0?'The mixture has thickened and changed colour and consistency. Pour it into the mold.':soapState===1?'Wait for it to set, then tap the soap to cut a bar.':'A new substance with a new consistency! Great work.'}</p><div style="text-align:center"><div class="mold" id="mold" style="display:inline-block" onclick="moldTap()">${soapState===0?'🫗':soapState===1?'🧼':'🧼'}</div></div></div>`;
app.innerHTML=`${header()}<main class="screen shell"><div class="playbar"><div><div class="progress-meta"><span>${isPractice?'PRACTICE LAB':'STAGE 20 / 20'}</span><span>${progress}% complete</span></div><div class="progress-track"><i style="width:${progress}%"></i></div></div>${stats()}</div><section class="stage-card hell"><div class="stage-kicker"><span>🔥 💀 ${esc(title)}</span><span class="difficulty">HELL IN A CELL</span></div><h1 class="stage-title">${isPractice?'Become a Soap Master':'The Soap Lab'}</h1><p class="stage-desc">${isPractice?'Practice the careful steps of saponification—at your own pace.':'You have mastered the science. Now make soap using oil, caustic soda and clockwise stirring.'}</p><div class="lab-layout"><div class="lab-visual"><span class="thermo">🌡️</span><div class="beaker"><div class="liquid" style="height:${liquidHeight}%;background:${liquidColor}"></div><div class="beaker-label">${labStep>=3?'Thickening mixture':'Reaction beaker'}</div></div><div class="lab-shelf"><span class="shelf-item">🫒 ${oilAmount||0} mL oil</span><span class="shelf-item">🧪 ${sodaAmount||0} mL NaOH</span></div></div><div id="lab-controls">${control}</div></div>${labStep>=4&&soapState===2?`<div class="lab-done"><div class="soap-icon">🧼✨</div><h2>SOAP FORMED!</h2><p>${stages[19].exp}</p><button class="primary" onclick="finishSoap()">Claim Soap Master title →</button></div>`:''}<div class="feedback" id="feedback"></div>${!isPractice&&labStep<4?`<div class="tip"><b>💡 Mister Ahmed’s Tip:</b> ${esc(stages[19].tip)}</div>`:''}</section>${footer()}</main>`;
if(labStep===3)bindStir(3,false);}
