function endScreen(){stopTimer();document.body.className='';app.innerHTML=`${header()}<main class="screen shell"><section class="stage-card certificate"><div class="trophy">🏆</div><div class="eyebrow">Mission accomplished · Stage 20 complete</div><h1 class="stage-title">You are a Soap Master!</h1><p class="stage-desc">You mastered heat, reactions, equations and nutrition—and made soap in Mister Ahmed’s lab.</p><div class="final-score">⭐ ${finalScore} <small>TOTAL POINTS</small></div><div class="cert"><div class="cert-inner"><div class="cert-top">SCIENCE LAB · CERTIFICATE OF ACHIEVEMENT</div><div class="cert-caption">This certifies that</div><h2>Junior Scientist</h2><p>has successfully completed the Matter Adventure and earned the title of</p><h3>SOAP MASTER</h3><div class="signature">Mister Ahmed Abdelhadi<span>Lab instructor</span></div><div class="watermark">Mister Ahmed Abdelhadi</div></div></div><button class="primary" onclick="confetti();home()">Back to the lab ⌂</button></section>${footer()}</main>`;confetti()}
function confetti(){const c=document.createElement('div');c.className='confetti';for(let i=0;i<75;i++){const p=document.createElement('i');p.style.left=Math.random()*100+'%';p.style.background=['#f2a640','#68ad72','#e5695f','#9976ce','#f4d75e'][i%5];p.style.animationDelay=Math.random()*1.3+'s';p.style.transform=`rotate(${Math.random()*180}deg)`;c.appendChild(p)}document.body.appendChild(c);setTimeout(()=>c.remove(),3600)}
home();
